//! The one opaque id every node row travels under.
//!
//! A stored row's id is a **UUID**, generated by whoever creates the row: a client may choose it,
//! and the server's own are UUIDv7. A row that existed before identity moved to UUIDs (ADR 0017,
//! decision 9) keeps the id it was always shown under, the UUID-v5 of `{kind}:{row number}`.
//!
//! A derived row — a Habit occurrence, a wait's check task — has no row to hold an id, so its id is
//! the hash of its value key (ADR 0008, decision 2), marked **version 8** (RFC 9562's custom
//! version). The mark is what tells the two apart on the wire, where both are UUID strings: a
//! stored id is never version 8, so [`NodeId`] reads the right variant without asking a database.
//!
//! The hash is computed here, in Rust. SQLite has no SHA-1 of its own, and registering one from
//! Rust would make the database unreadable to any other client that opened it.

use std::fmt;

use serde::{Deserialize, Deserializer, Serialize, Serializer};

pub use uuid::fmt::Hyphenated as RowId;

/// The namespace every derived node's UUID is hashed under.
///
/// The same namespace the frontend mints its display keys under (`ARLESH_NODE_NAMESPACE` in
/// `src/utils/node-uuid.ts`). Fixed for good: changing it changes every derived node's id.
pub const NODE_NAMESPACE: [u8; 16] = [
    0x0d, 0x75, 0xff, 0x4b, 0x96, 0x52, 0x45, 0x96, 0x9d, 0x2f, 0x19, 0x09, 0x23, 0x0b, 0x66, 0x2b,
];

/// The version nibble a derived id carries.
const DERIVED_VERSION: u8 = 8;

/// A text that is not a UUID was given as a row id.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("`{0}` is not a UUID")]
pub struct InvalidRowId(pub String);

/// The row id spelled by `text`, which must be a UUID.
pub fn parse_row_id(text: &str) -> Result<RowId, InvalidRowId> {
    uuid::Uuid::parse_str(text)
        .map(|id| id.hyphenated())
        .map_err(|_| InvalidRowId(text.to_string()))
}

/// The nil UUID: the id no row has. It stands where a row id is required but there is no row, as
/// the cycle pair of an occurrence no pair drew.
pub fn nil_row_id() -> RowId {
    uuid::Uuid::nil().hyphenated()
}

/// The row id with this number, for tests that need readable, distinct ids.
#[cfg(any(test, feature = "test-support"))]
pub fn test_row_id(number: u128) -> RowId {
    uuid::Uuid::from_u128(number | (0x7 << 76) | (0b10 << 62)).hyphenated()
}

/// Reads the `id` a caller chose for a row it is creating: absent, or a UUID that is neither the nil
/// UUID nor spelled as a derived node's (version 8), which no stored row may take.
pub fn deserialize_chosen_id<'de, D: Deserializer<'de>>(
    deserializer: D,
) -> Result<Option<RowId>, D::Error> {
    let Some(text) = Option::<String>::deserialize(deserializer)? else {
        return Ok(None);
    };
    let id = parse_row_id(&text).map_err(serde::de::Error::custom)?;
    if id == nil_row_id() || is_derived_spelling(&id) {
        return Err(serde::de::Error::custom(format!(
            "`{text}` cannot be the id of a new row: use a UUID, version 4 or 7, that is not the \
             nil UUID"
        )));
    }
    Ok(Some(id))
}

/// A row id for the number `number`, so a test can write `tid(3)` where it once wrote `3`.
#[cfg(any(test, feature = "test-support"))]
pub fn tid(number: i64) -> RowId {
    test_row_id(u128::from(number.unsigned_abs()))
}

/// The key a test writes `"task-5"` for: `{kind}-{id}` over the id `tid(number)`.
#[cfg(any(test, feature = "test-support"))]
pub fn tkey(kind: &str, number: i64) -> String {
    format!("{kind}-{}", tid(number))
}

/// A test writes `5.into()` for the stored node it once numbered 5.
#[cfg(any(test, feature = "test-support"))]
impl From<i64> for NodeId {
    fn from(number: i64) -> Self {
        Self::Stored(tid(number))
    }
}

/// Whether `id` is spelled as a derived node's: version 8.
pub fn is_derived_spelling(id: &RowId) -> bool {
    id.as_uuid().get_version_num() == usize::from(DERIVED_VERSION)
}

/// A derived node's id: the canonical `8-4-4-4-12` spelling of a version-8 UUID.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, schemars::JsonSchema)]
#[serde(transparent)]
pub struct DerivedId(String);

impl DerivedId {
    /// The id of the derived node whose canonical key is `node_key`.
    pub fn of_key(node_key: &str) -> Self {
        Self(uuid_hash(&NODE_NAMESPACE, node_key, DERIVED_VERSION))
    }

    /// An id already minted, read back from its spelling (a key that names another derived row).
    pub fn from_existing(spelling: &str) -> Self {
        Self(spelling.to_string())
    }

    /// The id as its hyphenated string.
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl<'de> Deserialize<'de> for DerivedId {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        String::deserialize(deserializer).map(Self)
    }
}

impl fmt::Display for DerivedId {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.0)
    }
}

/// Which row a node is: a stored one by its id, or a derived one by the hash of its key.
///
/// Both are UUID strings on the wire; the derived one's version nibble (8) says which it is.
#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum NodeId {
    /// A row of the kind's own table.
    Stored(RowId),
    /// A row derived from a template, overlaid with what makes it differ.
    Derived(DerivedId),
}

impl Serialize for NodeId {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        match self {
            Self::Stored(id) => id.serialize(serializer),
            Self::Derived(id) => id.serialize(serializer),
        }
    }
}

impl<'de> Deserialize<'de> for NodeId {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let text = String::deserialize(deserializer)?;
        text.parse::<NodeId>().map_err(serde::de::Error::custom)
    }
}

impl std::str::FromStr for NodeId {
    type Err = InvalidRowId;

    /// Reads a UUID: version 8 is a derived node's, anything else a stored row's.
    fn from_str(text: &str) -> Result<Self, Self::Err> {
        let id = parse_row_id(text)?;
        if is_derived_spelling(&id) {
            return Ok(Self::Derived(DerivedId::from_existing(&id.to_string())));
        }
        Ok(Self::Stored(id))
    }
}

impl schemars::JsonSchema for NodeId {
    fn schema_name() -> std::borrow::Cow<'static, str> {
        "NodeId".into()
    }

    fn json_schema(generator: &mut schemars::SchemaGenerator) -> schemars::Schema {
        let mut schema = generator.subschema_for::<String>();
        schema.insert(
            "description".to_string(),
            "A node's id: a UUID string (full id).".into(),
        );
        schema
    }
}

impl NodeId {
    /// The stored id, when this names a stored row.
    pub fn stored(&self) -> Option<RowId> {
        match self {
            Self::Stored(id) => Some(*id),
            Self::Derived(_) => None,
        }
    }

    /// The UUID, when this names a derived row.
    pub fn derived(&self) -> Option<&DerivedId> {
        match self {
            Self::Stored(_) => None,
            Self::Derived(id) => Some(id),
        }
    }

    /// Whether this names a derived row.
    pub fn is_derived(&self) -> bool {
        matches!(self, Self::Derived(_))
    }

    /// The stored id, or [`NotStored`] when this names a derived row — for a path that can only
    /// act on a row of the kind's own table, such as one it has just created.
    pub fn require_stored(&self) -> Result<RowId, NotStored> {
        match self {
            Self::Stored(id) => Ok(*id),
            Self::Derived(id) => Err(NotStored(id.clone())),
        }
    }
}

/// A derived node was named where only a stored row will do.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("node {0} is derived from a template and has no stored row")]
pub struct NotStored(pub DerivedId);

/// The id no row has: the nil UUID. It exists so a request can be built field by field with
/// `..Default::default()`; a request that reaches the database still naming it is refused there as
/// a missing parent.
impl Default for NodeId {
    fn default() -> Self {
        Self::Stored(nil_row_id())
    }
}

impl From<RowId> for NodeId {
    fn from(id: RowId) -> Self {
        Self::Stored(id)
    }
}

impl From<DerivedId> for NodeId {
    fn from(id: DerivedId) -> Self {
        Self::Derived(id)
    }
}

impl PartialEq<RowId> for NodeId {
    fn eq(&self, other: &RowId) -> bool {
        self.stored() == Some(*other)
    }
}

impl PartialEq<NodeId> for RowId {
    fn eq(&self, other: &NodeId) -> bool {
        other == self
    }
}

impl fmt::Display for NodeId {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Stored(id) => write!(formatter, "{id}"),
            Self::Derived(id) => write!(formatter, "{id}"),
        }
    }
}

/// A name-based (version 5) UUID of `name` under `namespace`, per RFC 9562.
pub fn uuid_v5(namespace: &[u8; 16], name: &str) -> String {
    uuid_hash(namespace, name, 5)
}

/// The SHA-1 of `name` under `namespace`, spelled as a UUID of `version`.
fn uuid_hash(namespace: &[u8; 16], name: &str, version: u8) -> String {
    let mut message = Vec::with_capacity(16 + name.len());
    message.extend_from_slice(namespace);
    message.extend_from_slice(name.as_bytes());
    let digest = sha1(&message);
    let mut bytes = [0u8; 16];
    bytes.copy_from_slice(&digest[..16]);
    bytes[6] = (bytes[6] & 0x0f) | (version << 4);
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    let hex: String = bytes.iter().map(|byte| format!("{byte:02x}")).collect();
    format!(
        "{}-{}-{}-{}-{}",
        &hex[0..8],
        &hex[8..12],
        &hex[12..16],
        &hex[16..20],
        &hex[20..32]
    )
}

/// SHA-1 of `message` (FIPS 180-4).
///
/// Used for what RFC 9562 uses it for — spreading a name deterministically over 122 bits — and
/// nothing secret, which is why a small local implementation stands in for a dependency. The
/// frontend carries the same one (`src/utils/uuid-v5.ts`).
fn sha1(message: &[u8]) -> [u8; 20] {
    let mut padded = message.to_vec();
    let bit_length = (message.len() as u64).wrapping_mul(8);
    padded.push(0x80);
    while padded.len() % 64 != 56 {
        padded.push(0);
    }
    padded.extend_from_slice(&bit_length.to_be_bytes());

    let mut state: [u32; 5] = [
        0x6745_2301,
        0xefcd_ab89,
        0x98ba_dcfe,
        0x1032_5476,
        0xc3d2_e1f0,
    ];
    for block in padded.chunks(64) {
        let mut words = [0u32; 80];
        for (index, chunk) in block.chunks(4).enumerate().take(16) {
            words[index] = u32::from_be_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
        }
        for index in 16..80 {
            words[index] =
                (words[index - 3] ^ words[index - 8] ^ words[index - 14] ^ words[index - 16])
                    .rotate_left(1);
        }
        let [mut a, mut b, mut c, mut d, mut e] = state;
        for (index, word) in words.iter().enumerate() {
            let (mixed, constant) = match index {
                0..=19 => ((b & c) | (!b & d), 0x5a82_7999),
                20..=39 => (b ^ c ^ d, 0x6ed9_eba1),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8f1b_bcdc),
                _ => (b ^ c ^ d, 0xca62_c1d6),
            };
            let next = a
                .rotate_left(5)
                .wrapping_add(mixed)
                .wrapping_add(e)
                .wrapping_add(constant)
                .wrapping_add(*word);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = next;
        }
        state[0] = state[0].wrapping_add(a);
        state[1] = state[1].wrapping_add(b);
        state[2] = state[2].wrapping_add(c);
        state[3] = state[3].wrapping_add(d);
        state[4] = state[4].wrapping_add(e);
    }

    let mut digest = [0u8; 20];
    for (index, word) in state.iter().enumerate() {
        digest[index * 4..index * 4 + 4].copy_from_slice(&word.to_be_bytes());
    }
    digest
}

